function getTimelineStatusKey(action: string): string {
  if (action === "started" || action === "claimed") return "in_progress";
  if (action === "moved_to_review") return "in_review";
  return action;
}

function ActivityNoteText({ text }: { text: string }) {
  const tokens = tokenizeText(text);
  return (
    <>
      {tokens.map((token, i) =>
        token.type === "link" ? (
          <a
            key={i}
            href={token.href}
            target="_blank"
            rel="noopener noreferrer"
            className="text-primary underline hover:opacity-80"
            data-task-activity-link
          >
            {token.label}
          </a>
        ) : (
          <span key={i}>{token.value}</span>
        ),
